package com.atlashub.pay.txquery.presentation.dto;
import com.atlashub.pay.txquery.application.queries.TransactionResults.TransactionResult;import org.springframework.stereotype.Component;
@Component public class TransactionResponseMapper {public TransactionResponse map(TransactionResult r){return new TransactionResponse(r.id(),r.type(),r.status(),r.amount(),r.fee(),r.netAmount(),r.currency(),r.direction(),r.channel(),r.provider(),r.reference(),r.sourceSystem(),r.sourceReferenceId(),r.partyType(),r.partyReferenceId(),r.outletId(),r.recipientName(),r.description(),r.metadata(),r.accountEntries().stream().map(e->new TransactionResponse.AccountEntryResponse(e.accountId(),e.accountType(),e.accountName(),e.entryType(),e.direction(),e.amount(),e.currency())).toList(),r.createdAt(),r.completedAt());}}
